dt-example.js:
const table = new DataTable('#example', {
	layout: {
		topStart: {
			buttons: ['stateCreate', 'statesList', 'pageLength']
		}
	},
	stateRestore: {
		bookmark: {
			src: '#'
		}
	}
});

const Dom = DataTable.Dom;
const list = Dom.s('#demo_info');

table.on('stateRestore', () => {
	const states = table.stateRestore.states().details();

	list.empty();

	states.forEach(s => {
		Dom.c('li')
			.append(
				Dom.c('a')
					.text(s.name)
					.attr('href', './userStates#' + s.id)
			)
			.appendTo(list);
	});
});
